schema:
entity Group;
entity User in [Group] {
  issuer: String,
  email: String,
  name: String,
  groups: Set<String>,
};
entity Route {
  site: String,
  mode: String,
};
action "GET", "HEAD", "POST", "PUT", "PATCH", "DELETE", "OPTIONS" appliesTo {
  principal: [User],
  resource: [Route],
  context: { path: String, method: String },
};
